const redondearAlPixel = (dp, densidad) => Math.round(dp * densidad) / densidad;
const lineaFina = (densidad) => {
  const h = redondearAlPixel(0.4, densidad);
  return h === 0 ? 1 / densidad : h;
};
for (const d of [1, 1.5, 2, 2.75, 3, 3.5]) {
  const f = lineaFina(d);
  console.log(`densidad ${d}: 16 dp = ${Math.round(16 * d)} px | línea fina = ${f.toFixed(3)} dp = ${Math.round(f * d)} px`);
}

